let csrf='';const msg=(id,text,ok=false)=>{const e=document.getElementById(id);e.className=ok?'ok':'err';e.textContent=text};async function load(){const r=await fetch('/api/account/settings');const d=await r.json();if(!r.ok){location.href='/login?next=%2Faccount-settings';return}csrf=d.csrf_token||'';email.value=d.account.email||'';name.value=d.account.name||''}saveProfile.onclick=async()=>{msg('profileMsg','');const r=await fetch('/api/account/settings',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({name:name.value})});const d=await r.json();msg('profileMsg',r.ok?'Profile updated.':(d.error||'Unable to update profile'),r.ok)};savePassword.onclick=async()=>{msg('passwordMsg','');const r=await fetch('/api/account/password',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({current_password:currentPassword.value,new_password:newPassword.value})});const d=await r.json();if(r.ok){currentPassword.value='';newPassword.value='';msg('passwordMsg','Password updated.',true)}else msg('passwordMsg',d.error||'Unable to change password')};load();
